-- Object types supported by Db2 COMMENT ON.
-- https://www.ibm.com/docs/en/db2/11.5?topic=statements-comment

COMMENT ON ALIAS MYALIAS IS 'comment';
COMMENT ON ALIAS MYALIAS FOR TABLE IS 'comment';
COMMENT ON PUBLIC ALIAS MYPUBLICALIAS IS 'comment';
COMMENT ON SYNONYM MYSYNONYM IS 'comment';
COMMENT ON SYNONYM MYSYNONYM FOR SEQUENCE IS 'comment';

COMMENT ON AUDIT POLICY MYAUDITPOLICY IS 'comment';

COMMENT ON COLUMN MYSCHEMA.MYTABLE.MYCOLUMN IS 'comment';

COMMENT ON CONSTRAINT MYSCHEMA.MYTABLE.MYCONSTRAINT IS 'comment';

COMMENT ON DATABASE PARTITION GROUP MYGROUP IS 'comment';
COMMENT ON NODEGROUP MYNODEGROUP IS 'comment';

COMMENT ON FUNCTION MYSCHEMA.MYFUNCTION IS 'comment';
COMMENT ON FUNCTION MYSCHEMA.MYFUNCTION (INT, FLOAT) IS 'comment';
COMMENT ON SPECIFIC FUNCTION MYSCHEMA.MYFUNCTION IS 'comment';
COMMENT ON FUNCTION MAPPING MYFUNCTIONMAPPING IS 'comment';

COMMENT ON HISTOGRAM TEMPLATE MYHISTOGRAMTEMPLATE IS 'comment';

COMMENT ON INDEX MYSCHEMA.MYINDEX IS 'comment';

COMMENT ON MASK MYSCHEMA.MYMASK IS 'comment';
COMMENT ON MODULE MYMODULE IS 'comment';
COMMENT ON NICKNAME MYNICKNAME IS 'comment';

COMMENT ON PACKAGE MYSCHEMA.MYPACKAGE VERSION "V1" IS 'comment';
COMMENT ON PACKAGE MYSCHEMA.MYPACKAGE VERSION 8.0.3 IS 'comment';

COMMENT ON PERMISSION MYPERMISSION IS 'comment';

COMMENT ON PROCEDURE MYSCHEMA.MYPROCEDURE IS 'comment';
COMMENT ON PROCEDURE MYSCHEMA.MYPROCEDURE (CHAR, INT) IS 'comment';
COMMENT ON SPECIFIC PROCEDURE MYSCHEMA.MYPROCEDURE IS 'comment';

COMMENT ON ROLE MYROLE IS 'comment';
COMMENT ON SCHEMA MYSCHEMA IS 'comment';

COMMENT ON SECURITY LABEL MYSCHEMA.MYSECURITYLABEL IS 'comment';
COMMENT ON SECURITY LABEL COMPONENT MYSCHEMA.MYCOMPONENT IS 'comment';
COMMENT ON SECURITY POLICY MYSCHEMA.MYSECURITYPOLICY IS 'comment';

COMMENT ON SEQUENCE MYSCHEMA.MYSEQUENCE IS 'comment';

COMMENT ON SERVER MYSERVER IS 'comment';
COMMENT ON SERVER OPTION MYSERVEROPTION FOR SERVER MYSERVER
    SERVER TYPE DB2 VERSION '8.2.3' IS 'comment';
COMMENT ON SERVER OPTION MYWRAPPEROPTION FOR WRAPPER MYWRAPPER
    VERSION '8.2.3' IS 'comment';
COMMENT ON SERVER OPTION MYSERVEROPTION FOR SERVER MYSERVER
    SERVER TYPE DB2 VERSION 8.2.3 IS 'comment';

COMMENT ON SERVICE CLASS MYSERVICECLASS IS 'comment';
COMMENT ON SERVICE CLASS MYSUBCLASS UNDER MYSUPERCLASS IS 'comment';
COMMENT ON STOGROUP MYSTOGROUP IS 'comment';

COMMENT ON TABLE MYSCHEMA.MYTABLE IS 'comment';
COMMENT ON TABLESPACE MYTABLESPACE IS 'comment';
COMMENT ON THRESHOLD MYTHRESHOLD IS 'comment';
COMMENT ON TRIGGER MYSCHEMA.MYTRIGGER IS 'comment';
COMMENT ON TRUSTED CONTEXT MYTRUSTEDCONTEXT IS 'comment';

COMMENT ON TYPE MYSCHEMA.MYTYPE IS 'comment';
COMMENT ON TYPE MAPPING MYSCHEMA.MYTYPEMAPPING IS 'comment';
COMMENT ON DISTINCT TYPE MYSCHEMA.MYDISTINCTTYPE IS 'comment';
COMMENT ON DATA TYPE MYSCHEMA.MYDATATYPE IS 'comment';

COMMENT ON USAGE LIST MYUSAGELIST IS 'comment';
COMMENT ON VARIABLE MYSCHEMA.MYVARIABLE IS 'comment';
COMMENT ON VIEW MYSCHEMA.MYVIEW IS 'comment';

COMMENT ON WORK ACTION SET MYWORKACTIONSET IS 'comment';
COMMENT ON WORK CLASS SET MYWORKCLASSSET IS 'comment';
COMMENT ON WORKLOAD MYWORKLOAD IS 'comment';

COMMENT ON WRAPPER MYWRAPPER IS 'comment';
COMMENT ON XSROBJECT MYSCHEMA.MYXSROBJECT IS 'comment';

COMMENT ON MYSCHEMA.MYTABLE (
    COL1 IS 'first column',
    COL2 IS 'second column'
);
